Method.Source:
public void insert()
{
    next insert();

    if (this.METCachedAttributeType != METCachedAttributeTypeEnum::None)
    {
        this.addOrUpdateCachedAttributes();
    }
}

public void update()
{
    next update();

    if (this.METCachedAttributeType != METCachedAttributeTypeEnum::None)
    {
        this.addOrUpdateCachedAttributes();
    }
}

public boolean validateWrite()
{
    EcoResAttributeType attributeType;
    boolean             ret;

    // Run base validation first
    ret = next validateWrite();

    if (!ret)
    {
        return ret;
    }

    if (this.METCachedAttributeType != METCachedAttributeTypeEnum::None)
    {
        attributeType = EcoResAttributeType::find(this.AttributeType);

        if ((this.METCachedAttributeType == METCachedAttributeTypeEnum::ConsumerGSTExempt
                || this.METCachedAttributeType == METCachedAttributeTypeEnum::PricedByWeight
                || this.METCachedAttributeType == METCachedAttributeTypeEnum::TempItemForPackChange)
                    && attributeType.DataType != AttributeDataType::TrueFalse)
        {                
            ret = false;   
            error(strFmt("@MET:CachedAttributeTypeValidationError", AttributeDataType::TrueFalse, '@MET:CachedAttributeType', this.METCachedAttributeType));
        }

        if ((this.METCachedAttributeType == METCachedAttributeTypeEnum::InvoiceCategory
                || this.METCachedAttributeType == METCachedAttributeTypeEnum::LevyType)
                    && attributeType.DataType != AttributeDataType::Text)
        {
            ret = false;
            error(strFmt("@MET:CachedAttributeTypeValidationError", AttributeDataType::Text, '@MET:CachedAttributeType', this.METCachedAttributeType));
        }           
    }

    return ret;
}

public void addOrUpdateCachedAttributes()
{
    EcoResProductParameters ecoResProductParameters = EcoResProductParameters::find();

    if (ecoResProductParameters.RecId)
    {
        ecoResProductParameters.selectForUpdate(true);
        this.setCachedAttributes(ecoResProductParameters);
        ecoResProductParameters.update();
    }
    else
    {
        this.setCachedAttributes(ecoResProductParameters);
        ecoResProductParameters.insert();
    }
}

public void setCachedAttributes(EcoResProductParameters _ecoResProductParameters)
{
    switch (this.METCachedAttributeType)
    {
        case METCachedAttributeTypeEnum::ConsumerGSTExempt:
            _ecoResProductParameters.METConsumerGSTExempt = this.RecId;
            break;
        case METCachedAttributeTypeEnum::InvoiceCategory:
            _ecoResProductParameters.METInvoiceCategory = this.RecId;
            break;
        case METCachedAttributeTypeEnum::LevyType:
            _ecoResProductParameters.METLevyType = this.RecId;
            break;
        case METCachedAttributeTypeEnum::PricedByWeight:
            _ecoResProductParameters.METPricedByWeight = this.RecId;
            break;
        case METCachedAttributeTypeEnum::TempItemForPackChange:
            _ecoResProductParameters.METTempItemForPackChange = this.RecId;
            break;
    }
}
